mkdir -p /tmp/frai-test && cd /tmp/frai-test && node -e "
fs = require('fs');
fs.writeFileSync('outputs.json', JSON.stringify(['hello world', 'good morning', 'how are you'], null, 2));
fs.writeFileSync('references.json', JSON.stringify(['hello world', 'good morning', 'how are you'], null, 2));
console.log('Test files created');
"
ls -la /tmp/frai-test/

cd /private/tmp/100-tricks-runs/d03/with/h2-eval-thresholds/r1 && cat > _test_scenario.js << 'EOF'
import { Eval } from 'frai-core';
import fs from 'fs';
import path from 'path';

// Create test data
const outputs = ['Hello World', 'Good Morning'];
const references = ['Hello World', 'Good Morning'];

// Run evaluations
const evaluations = Eval.runEvaluations({ outputs, references });

console.log('Metric IDs available:', evaluations.map(m => m.id).join(', '));

// Test 1: Report with passing thresholds
const report1 = Eval.generateReport({
  evaluations,
  outputsPath: 'outputs.json',
  referencesPath: 'refs.json',
  thresholds: { exact_match: 0.5, length_variance: 0.8 }
});

console.log('\nTest 1 - Passing thresholds:');
console.log('  passed:', report1.passed);
console.log('  thresholds count:', report1.thresholds?.length || 0);

// Test 2: Report with failing threshold
const report2 = Eval.generateReport({
  evaluations,
  outputsPath: 'outputs.json',
  referencesPath: 'refs.json',
  thresholds: { exact_match: 0.99 }
});

console.log('\nTest 2 - Failing threshold:');
console.log('  passed:', report2.passed);
console.log('  threshold[0]:', {
  metric: report2.thresholds[0].metric,
  score: report2.thresholds[0].score,
  min: report2.thresholds[0].min,
  passed: report2.thresholds[0].passed
});

// Test 3: Report without thresholds
const report3 = Eval.generateReport({
  evaluations,
  outputsPath: 'outputs.json',
  referencesPath: 'refs.json'
});

console.log('\nTest 3 - No thresholds:');
console.log('  has passed field:', 'passed' in report3);
console.log('  has thresholds field:', 'thresholds' in report3);

console.log('\n✅ All SDK tests passed!');
EOF
node _test_scenario.js
